-- FE科目Aに対応したオリジナル実戦ケース24件。IPAの公式過去問ではありません。
-- SG既存データは変更せず、実戦題目の試験区分のみ追加します。
ALTER TABLE practical_scenarios ADD COLUMN exam_section TEXT CHECK (exam_section IN ('A', 'B'));
CREATE INDEX IF NOT EXISTS idx_scenarios_track_section ON practical_scenarios(track_id, exam_section, category);
INSERT OR IGNORE INTO practical_scenarios (id,track_id,title,category,difficulty,situation,task,options_json,best_option,scoring_json,explanation,source_type,exam_section) VALUES ('fe-scenario-a-001','exam-fe','CPUの性能比較','コンピュータ構成','intermediate','CPU Aはクロック周波数3GHzで平均CPIが1.5、CPU Bは2GHzで平均CPIが0.8。同じ命令数のプログラムを実行する。','命令数が同じとき、実行時間の比較として正しいのはどれか。','[{"id":"a","text":"Aの実行時間はBの半分になる"},{"id":"b","text":"BはAより速く、実行時間はAの約0.8倍になる"},{"id":"c","text":"両者は同じ実行時間になる"},{"id":"d","text":"クロック周波数だけでAが必ず速い"}]','b','{"a":0,"b":100,"c":0,"d":0}','実行時間は命令数×CPI÷クロック周波数。Aは1.5/3=0.5、Bは0.8/2=0.4（比例値）なのでBの方が速く、B/A=0.8。','authored','A');
INSERT OR IGNORE INTO practical_scenarios (id,track_id,title,category,difficulty,situation,task,options_json,best_option,scoring_json,explanation,source_type,exam_section) VALUES ('fe-scenario-a-002','exam-fe','キューを用いる処理','データ構造','standard','Webサーバに到着したジョブを、受け付けた順に1件ずつ処理する必要がある。','待ち行列の操作に適したデータ構造はどれか。','[{"id":"a","text":"LIFOのスタック"},{"id":"b","text":"FIFOのキュー"},{"id":"c","text":"同じ値を除く集合"},{"id":"d","text":"順序を持たないハッシュ集合"}]','b','{"a":0,"b":100,"c":0,"d":0}','先着順はFIFOであり、末尾への追加と先頭からの取出しを行うキューが適する。','authored','A');
INSERT OR IGNORE INTO practical_scenarios (id,track_id,title,category,difficulty,situation,task,options_json,best_option,scoring_json,explanation,source_type,exam_section) VALUES ('fe-scenario-a-003','exam-fe','二分探索の前提','データ構造','standard','1000件の会員番号から対象を探索する。配列の要素は会員番号の昇順で整列している。','二分探索の特徴として正しいのはどれか。','[{"id":"a","text":"整列済みなら比較回数のオーダーはO(log n)"},{"id":"b","text":"データが未整列であることが前提"},{"id":"c","text":"比較回数は常にn回"},{"id":"d","text":"中央の値を調べず先頭から順に比較する"}]','a','{"a":100,"b":0,"c":0,"d":0}','二分探索はソート済み配列の中央と比較して探索範囲を半分ずつ狭めるためO(log n)。','authored','A');
INSERT OR IGNORE INTO practical_scenarios (id,track_id,title,category,difficulty,situation,task,options_json,best_option,scoring_json,explanation,source_type,exam_section) VALUES ('fe-scenario-a-004','exam-fe','SQL結合と件数','データベース','intermediate','顧客表には顧客が3件、注文表には顧客Aの注文が2件、顧客Bの注文が1件あり、顧客Cには注文がない。','顧客表を左表としてLEFT JOINしたときの行数はどれか。','[{"id":"a","text":"3行"},{"id":"b","text":"4行"},{"id":"c","text":"2行"},{"id":"d","text":"6行"}]','b','{"a":0,"b":100,"c":0,"d":0}','LEFT JOINは注文のない顧客CもNULL付きで保持する。A2行+B1行+C1行の合計4行。','authored','A');
INSERT OR IGNORE INTO practical_scenarios (id,track_id,title,category,difficulty,situation,task,options_json,best_option,scoring_json,explanation,source_type,exam_section) VALUES ('fe-scenario-a-005','exam-fe','トランザクションの整合性','データベース','standard','銀行システムで口座Aから口座Bに送金する。Aの残高減額後に障害が起きる可能性がある。','残高不一致を防ぐ設計として適切なのはどれか。','[{"id":"a","text":"Aの減額だけを先に確定する"},{"id":"b","text":"2つの更新を同じトランザクションで行い、失敗時はロールバックする"},{"id":"c","text":"Bの増額を別日のバッチへ送る"},{"id":"d","text":"エラー時にはログだけ残して減額を確定する"}]','b','{"a":0,"b":100,"c":0,"d":0}','送金を構成する更新は一体として成功・失敗させる。原子性を確保するトランザクションが必要。','authored','A');
INSERT OR IGNORE INTO practical_scenarios (id,track_id,title,category,difficulty,situation,task,options_json,best_option,scoring_json,explanation,source_type,exam_section) VALUES ('fe-scenario-a-006','exam-fe','CIDRのホスト数','ネットワーク','standard','IPv4ネットワーク192.0.2.0/27を、通常のネットワークアドレス・ブロードキャストアドレスを予約するホストネットワークとして使う。','利用可能なホストアドレス数はどれか。','[{"id":"a","text":"16個"},{"id":"b","text":"30個"},{"id":"c","text":"32個"},{"id":"d","text":"62個"}]','b','{"a":0,"b":100,"c":0,"d":0}','/27はホスト部5ビットで32アドレス。ネットワークアドレスとブロードキャストを除き30個。','authored','A');
INSERT OR IGNORE INTO practical_scenarios (id,track_id,title,category,difficulty,situation,task,options_json,best_option,scoring_json,explanation,source_type,exam_section) VALUES ('fe-scenario-a-007','exam-fe','DNS障害の切り分け','ネットワーク','intermediate','IPアドレスを指定するとサービスに接続できるが、ホスト名でアクセスすると名前解決エラーになる。','最初に確認すべき構成要素はどれか。','[{"id":"a","text":"名前解決に用いるDNS設定とレコード"},{"id":"b","text":"CPUのL2キャッシュ容量"},{"id":"c","text":"モニタの画面解像度"},{"id":"d","text":"キーボードの入力方式"}]','a','{"a":100,"b":0,"c":0,"d":0}','IP到達性がある一方、ホスト名で失敗する場合はDNSサーバ設定・レコード・キャッシュを確認する。','authored','A');
INSERT OR IGNORE INTO practical_scenarios (id,track_id,title,category,difficulty,situation,task,options_json,best_option,scoring_json,explanation,source_type,exam_section) VALUES ('fe-scenario-a-008','exam-fe','SQLインジェクションの対策','セキュリティ','standard','検索画面でユーザが入力したキーワードを文字列連結してSQLを生成している。','根本的な対策として最も適切なのはどれか。','[{"id":"a","text":"入力文字列をそのままSQLへ連結する"},{"id":"b","text":"プレースホルダとバインド変数を利用する"},{"id":"c","text":"エラーメッセージだけ隠してSQLはそのままにする"},{"id":"d","text":"管理者権限で接続して失敗を減らす"}]','b','{"a":0,"b":100,"c":0,"d":0}','パラメータ化クエリによりデータとSQL構文を分離し、不正入力が構文として実行されないようにする。','authored','A');
INSERT OR IGNORE INTO practical_scenarios (id,track_id,title,category,difficulty,situation,task,options_json,best_option,scoring_json,explanation,source_type,exam_section) VALUES ('fe-scenario-a-009','exam-fe','パスワードの保管','セキュリティ','standard','新しいWebサービスを開発する。認証時に入力パスワードを照合する必要がある。','サーバ側の保存方法として推奨されるのはどれか。','[{"id":"a","text":"平文で保存する"},{"id":"b","text":"各利用者に固有のソルトを使い、専用の低速ハッシュ方式で保存する"},{"id":"c","text":"同じ秘密鍵で可逆暗号化した値だけを保存する"},{"id":"d","text":"MD5で一度だけハッシュする"}]','b','{"a":0,"b":100,"c":0,"d":0}','Argon2idなどのパスワード用ハッシュ方式と個別ソルトを利用し、検証時に一致を確認する。','authored','A');
INSERT OR IGNORE INTO practical_scenarios (id,track_id,title,category,difficulty,situation,task,options_json,best_option,scoring_json,explanation,source_type,exam_section) VALUES ('fe-scenario-a-010','exam-fe','単体テストの境界値','ソフトウェア開発','intermediate','年齢は18歳以上65歳以下のみ登録可能という要件がある。','境界値テストで特に有効な入力の組合せはどれか。','[{"id":"a","text":"18と65だけ"},{"id":"b","text":"17、18、65、66"},{"id":"c","text":"20、30、40、50"},{"id":"d","text":"0と100だけ"}]','b','{"a":0,"b":100,"c":0,"d":0}','範囲の内側・外側を比較するため境界直前・境界値を使う。17、18、65、66を確認する。','authored','A');
INSERT OR IGNORE INTO practical_scenarios (id,track_id,title,category,difficulty,situation,task,options_json,best_option,scoring_json,explanation,source_type,exam_section) VALUES ('fe-scenario-a-011','exam-fe','レビュー時のデータ変更','ソフトウェア開発','standard','新機能をデプロイするとデータベースの列名が変わる。旧バージョンのアプリも一時的に動く。','無停止移行に適した順序はどれか。','[{"id":"a","text":"先に旧列を削除してから新コードを配置"},{"id":"b","text":"互換列を追加し新旧コードが動く状態を作り、移行後に旧列を削除する"},{"id":"c","text":"データを全消去して新列だけ作る"},{"id":"d","text":"テストなしで全ての変更を一度に実行する"}]','b','{"a":0,"b":100,"c":0,"d":0}','expand-and-contract方式で互換性を維持し、バックフィルや動作確認後に不要な列を削除する。','authored','A');
INSERT OR IGNORE INTO practical_scenarios (id,track_id,title,category,difficulty,situation,task,options_json,best_option,scoring_json,explanation,source_type,exam_section) VALUES ('fe-scenario-a-012','exam-fe','可用性の直列系','システム構成','standard','直列に依存する2台の装置があり、それぞれの稼働率は独立に0.9である。','システム全体の稼働率はどれか。','[{"id":"a","text":"0.99"},{"id":"b","text":"0.90"},{"id":"c","text":"0.81"},{"id":"d","text":"0.18"}]','c','{"a":0,"b":0,"c":100,"d":0}','両方同時に稼働する確率は0.9×0.9=0.81。直列システムの可用性は各稼働率の積。','authored','A');
INSERT OR IGNORE INTO practical_scenarios (id,track_id,title,category,difficulty,situation,task,options_json,best_option,scoring_json,explanation,source_type,exam_section) VALUES ('fe-scenario-a-013','exam-fe','RAIDの選択','システム構成','intermediate','ディスク1台の障害に耐えたい。2台のディスクに同一データを書き込む構成を検討している。','該当する方式はどれか。','[{"id":"a","text":"RAID 0のストライピング"},{"id":"b","text":"RAID 1のミラーリング"},{"id":"c","text":"JBODで単純連結"},{"id":"d","text":"暗号化のみを行う方式"}]','b','{"a":0,"b":100,"c":0,"d":0}','RAID 1は同一内容を複数のディスクに記録し、1台の故障に耐える。ただしバックアップの代わりにはならない。','authored','A');
INSERT OR IGNORE INTO practical_scenarios (id,track_id,title,category,difficulty,situation,task,options_json,best_option,scoring_json,explanation,source_type,exam_section) VALUES ('fe-scenario-a-014','exam-fe','仮想記憶とページフォールト','OS・メモリ','standard','プロセスが必要とするページが主記憶上に存在しないため、補助記憶から読み込む必要がある。','この現象の名称はどれか。','[{"id":"a","text":"ページフォールト"},{"id":"b","text":"デッドコード"},{"id":"c","text":"スプーフィング"},{"id":"d","text":"キャッシュヒット"}]','a','{"a":100,"b":0,"c":0,"d":0}','必要なページが主記憶にない場合ページフォールトが発生し、ページングによりページを読み込む。','authored','A');
INSERT OR IGNORE INTO practical_scenarios (id,track_id,title,category,difficulty,situation,task,options_json,best_option,scoring_json,explanation,source_type,exam_section) VALUES ('fe-scenario-a-015','exam-fe','デッドロックの回避','OS・メモリ','standard','複数スレッドがロックAとロックBを取得する。スレッド1はA→B、スレッド2はB→Aの順で取得する。','デッドロックのリスクを減らす方法はどれか。','[{"id":"a","text":"両スレッドで必ずA→Bの順に取得する"},{"id":"b","text":"待機中はログを削除する"},{"id":"c","text":"ロックを共有パスワードで保護する"},{"id":"d","text":"すべてのスレッドの優先度を最大にする"}]','a','{"a":100,"b":0,"c":0,"d":0}','ロック取得順序を統一すると循環待ちを防止でき、デッドロックの必要条件の一つを崩せる。','authored','A');
INSERT OR IGNORE INTO practical_scenarios (id,track_id,title,category,difficulty,situation,task,options_json,best_option,scoring_json,explanation,source_type,exam_section) VALUES ('fe-scenario-a-016','exam-fe','索引と検索性能','データベース','intermediate','大きな取引テーブルからaccount_idで等価検索するクエリが遅い。account_id列には索引がない。','まず有効性を検討すべき施策はどれか。','[{"id":"a","text":"account_idに適切なインデックスを作り実行計画を確認する"},{"id":"b","text":"毎回全表を手動で並べ替える"},{"id":"c","text":"WHERE句を削除する"},{"id":"d","text":"取引IDを全て同じ値にする"}]','a','{"a":100,"b":0,"c":0,"d":0}','選択性や更新負荷を踏まえてインデックスを検討し、実行計画で利用状況を検証する。','authored','A');
INSERT OR IGNORE INTO practical_scenarios (id,track_id,title,category,difficulty,situation,task,options_json,best_option,scoring_json,explanation,source_type,exam_section) VALUES ('fe-scenario-a-017','exam-fe','クリティカルパス','プロジェクト管理','standard','工程Aは3日、BはAの後に4日、CはAの後に2日、DはBとCが完了後に1日かかる。','最短完了期間は何日か。','[{"id":"a","text":"6日"},{"id":"b","text":"7日"},{"id":"c","text":"8日"},{"id":"d","text":"10日"}]','c','{"a":0,"b":0,"c":100,"d":0}','A→B→Dは3+4+1=8日、A→C→Dは3+2+1=6日。長い方がクリティカルパスで8日。','authored','A');
INSERT OR IGNORE INTO practical_scenarios (id,track_id,title,category,difficulty,situation,task,options_json,best_option,scoring_json,explanation,source_type,exam_section) VALUES ('fe-scenario-a-018','exam-fe','リスク対策の優先順位','マネジメント','standard','障害発生確率が0.05、発生時損失が200万円のリスクと、確率0.20、損失50万円のリスクがある。','期待損失の比較として正しいのはどれか。','[{"id":"a","text":"前者が10万円、後者も10万円"},{"id":"b","text":"前者が100万円、後者が10万円"},{"id":"c","text":"前者が10万円、後者が1万円"},{"id":"d","text":"確率だけを見れば前者が大きい"}]','a','{"a":100,"b":0,"c":0,"d":0}','期待損失は確率×損失額。0.05×200万円=10万円、0.2×50万円=10万円。','authored','A');
INSERT OR IGNORE INTO practical_scenarios (id,track_id,title,category,difficulty,situation,task,options_json,best_option,scoring_json,explanation,source_type,exam_section) VALUES ('fe-scenario-a-019','exam-fe','計算量の見積り','アルゴリズム基礎','intermediate','配列の各要素について、別の配列全体を先頭から最後まで走査する。両配列の要素数をnとする。','処理回数のオーダーはどれか。','[{"id":"a","text":"O(1)"},{"id":"b","text":"O(log n)"},{"id":"c","text":"O(n)"},{"id":"d","text":"O(n²)"}]','d','{"a":0,"b":0,"c":0,"d":100}','二重ループで各ループがn回ずつ実行されるため、合計n²回となる。','authored','A');
INSERT OR IGNORE INTO practical_scenarios (id,track_id,title,category,difficulty,situation,task,options_json,best_option,scoring_json,explanation,source_type,exam_section) VALUES ('fe-scenario-a-020','exam-fe','再帰処理の終了条件','アルゴリズム基礎','standard','階乗を再帰関数で実装する。入力nは0以上の整数とする。','無限再帰を防ぐための基本条件はどれか。','[{"id":"a","text":"nが0のとき1を返し再帰を終える"},{"id":"b","text":"nが0のとき再帰関数を呼び直す"},{"id":"c","text":"nを毎回2倍して呼び直す"},{"id":"d","text":"呼出し回数を記録するだけにする"}]','a','{"a":100,"b":0,"c":0,"d":0}','0!=1を基底条件とし、n>0の場合にn×factorial(n-1)を計算する。','authored','A');
INSERT OR IGNORE INTO practical_scenarios (id,track_id,title,category,difficulty,situation,task,options_json,best_option,scoring_json,explanation,source_type,exam_section) VALUES ('fe-scenario-a-021','exam-fe','SQL集計の対象','データベース','standard','販売表に金額10、20、NULLの3行がある。','SELECT COUNT(金額), COUNT(*), SUM(金額) の結果はどれか。','[{"id":"a","text":"3、3、30"},{"id":"b","text":"2、3、30"},{"id":"c","text":"2、2、30"},{"id":"d","text":"3、2、NULL"}]','b','{"a":0,"b":100,"c":0,"d":0}','COUNT(列)はNULLを除くため2、COUNT(*)は3、SUMもNULLを除くため30。','authored','A');
INSERT OR IGNORE INTO practical_scenarios (id,track_id,title,category,difficulty,situation,task,options_json,best_option,scoring_json,explanation,source_type,exam_section) VALUES ('fe-scenario-a-022','exam-fe','TCPとUDPの選択','ネットワーク','intermediate','アプリは短い要求と応答を交換する。パケット損失時にはアプリ自身が再送を管理し、遅延を最小化したい。','一般に検討するトランスポートプロトコルはどれか。','[{"id":"a","text":"UDP"},{"id":"b","text":"TCPしか使えない"},{"id":"c","text":"SMTP"},{"id":"d","text":"ICMPだけでアプリの双方向通信を行う"}]','a','{"a":100,"b":0,"c":0,"d":0}','UDPはコネクション確立や順序制御を必須としない。信頼性が必要ならアプリ層で再送・順序制御を設計する。','authored','A');
INSERT OR IGNORE INTO practical_scenarios (id,track_id,title,category,difficulty,situation,task,options_json,best_option,scoring_json,explanation,source_type,exam_section) VALUES ('fe-scenario-a-023','exam-fe','公開鍵暗号の利用','セキュリティ','standard','サーバから取得するソフトウェア配布物が、配布者によって署名されたものか検証したい。','署名検証に利用する鍵として正しいのはどれか。','[{"id":"a","text":"署名者の公開鍵"},{"id":"b","text":"検証者の秘密鍵"},{"id":"c","text":"署名者の秘密鍵を配布する"},{"id":"d","text":"共通鍵を全利用者に公開する"}]','a','{"a":100,"b":0,"c":0,"d":0}','デジタル署名は署名者の秘密鍵で作成し、対応する公開鍵で検証する。公開鍵自体の正当性も確認する。','authored','A');
INSERT OR IGNORE INTO practical_scenarios (id,track_id,title,category,difficulty,situation,task,options_json,best_option,scoring_json,explanation,source_type,exam_section) VALUES ('fe-scenario-a-024','exam-fe','キャッシュの整合性','システム構成','standard','商品価格を更新したが、利用者には数分前の価格が表示されている。Webアプリは価格一覧をキャッシュしている。','最初に確認すべき点はどれか。','[{"id":"a","text":"キャッシュの有効期限と更新時の無効化処理"},{"id":"b","text":"ユーザのディスプレイの明るさ"},{"id":"c","text":"CPUのクロック倍率"},{"id":"d","text":"キーボード配列"}]','a','{"a":100,"b":0,"c":0,"d":0}','価格更新時のキャッシュ無効化とTTLを確認し、更新伝播や古いキャッシュを調査する。','authored','A');
